import React from 'react';
import {AbsoluteFill} from 'remotion';
import {useS, en, fin, T, DUR, Camara, Subtitulos, Contador, Textura, Profundidad, Brillo, Paso, seguir, enCamino, tono, Regla, Chip, Ondas, Destello, sacudida, golpe, Recorrido, Easing, interpolate, clamp, spring, h, FONT} from './kit';

// ---------- utilidades ----------
const cl = (v: number, a = 0, b = 1) => Math.max(a, Math.min(b, v));
const eo = (x: number) => 1 - Math.pow(1 - cl(x), 3);
const eio = (x: number) => { const k = cl(x); return k < 0.5 ? 4 * k * k * k : 1 - Math.pow(-2 * k + 2, 3) / 2; };
const ro = (s: number, a: number, b: number) => cl((s - a) / (b - a));
// parada de camara que nunca deja ver el borde del fondo
const P = (t: number, x: number, y: number, z: number) => ({t, x: cl(x, 540 / z, 1080 - 540 / z), y: cl(y, 1000 / z, 1920 - 920 / z), zoom: z});
const GOLD = '#FFC83D';
const RED = '#FF4D4D';
const PIEL = '#c98f5e';
const BR = (s: number) => 1 + Math.sin(s * 2.4) * 0.03;
// SFX: nunca dos a menos de 0,27 s aunque la voz real cambie los tiempos
const fix = (l: {t: number; s: string}[]) => {
  const o: {t: number; s: string}[] = [];
  let last = -9;
  [...l].sort((a, b) => a.t - b.t).forEach((e) => { if (e.t - last >= 0.27) { o.push(e); last = e.t; } });
  return o;
};

// ---------- piezas dibujadas ----------
const Bill: React.FC<{x: number; y: number; r?: number; k?: number; txt?: string; tint?: string; halo?: string}> = ({x, y, r = 0, k = 1, txt = '70', tint = '#b4d9a2', halo}) => (
  <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
    {halo && <ellipse rx={240} ry={160} fill={halo} opacity={0.4} />}
    <rect x={-146} y={-60} width={304} height={144} rx={14} fill="rgba(0,0,0,0.35)" />
    <rect x={-150} y={-70} width={300} height={140} rx={14} fill={tint} stroke="#3f6b3a" strokeWidth={5} />
    <rect x={-134} y={-54} width={268} height={108} rx={9} fill="none" stroke="#3f6b3a" strokeWidth={2.5} opacity={0.65} />
    <circle r={42} fill="rgba(255,255,255,0.35)" stroke="#3f6b3a" strokeWidth={3} />
    <text y={15} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={txt.length > 2 ? 32 : 46} fill="#2f5a2b">{txt}</text>
    <text x={-122} y={-28} fontFamily={FONT} fontWeight={800} fontSize={26} fill="#2f5a2b">$</text>
    <text x={100} y={50} fontFamily={FONT} fontWeight={800} fontSize={26} fill="#2f5a2b">$</text>
    <path d="M -150 -70 L 24 -70 L -56 70 L -150 70 Z" fill="rgba(255,255,255,0.16)" />
  </g>
);

const Cartera: React.FC<{x: number; y: number; k?: number; r?: number; grosor?: number; oro?: boolean; abierta?: number}> = ({x, y, k = 1, r = 0, grosor = 1, oro = false, abierta = 0}) => (
  <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
    <defs>
      <linearGradient id="cuero" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#8a5a34" /><stop offset="60%" stopColor="#5f3a1f" /><stop offset="100%" stopColor="#3d2312" /></linearGradient>
    </defs>
    <ellipse cx={0} cy={140} rx={210} ry={26} fill="rgba(0,0,0,0.4)" />
    {[0, 1, 2].map((i) => <rect key={i} x={-150 + i * 26} y={-150 - 62 * grosor * (1 - i * 0.12) + abierta * -50} width={250} height={90 * grosor + 20} rx={8} fill={['#b4d9a2', '#a3cf92', '#c1e2b2'][i]} stroke="#3f6b3a" strokeWidth={3} transform={`rotate(${(i - 1) * 4})`} />)}
    <rect x={-190} y={-120} width={380} height={250} rx={30} fill="url(#cuero)" stroke="#2c180a" strokeWidth={5} />
    <rect x={-170} y={-100} width={340} height={210} rx={20} fill="none" stroke={oro ? GOLD : '#c9a074'} strokeWidth={3} strokeDasharray="12 9" opacity={0.85} />
    <path d="M -190 -40 Q 0 -10 190 -40 L 190 -80 Q 0 -110 -190 -80 Z" fill="rgba(255,255,255,0.10)" />
    <rect x={120} y={-24} width={70} height={64} rx={14} fill={oro ? GOLD : '#7a4c28'} stroke="#2c180a" strokeWidth={4} />
    <circle cx={152} cy={8} r={12} fill={oro ? '#fff2b0' : '#c9a074'} />
  </g>
);

const Mano: React.FC<{x: number; y: number; r?: number; k?: number; dedo?: boolean; guante?: boolean}> = ({x, y, r = 0, k = 1, dedo = true, guante = false}) => {
  const F = guante ? 'url(#guanteM)' : 'url(#piel9)';
  const L = guante ? '#0b0d12' : '#7a4f2c';
  return (
    <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
      <defs>
        <linearGradient id="piel9" x1="0" y1="0" x2="1" y2="0"><stop offset="0%" stopColor="#e0a878" /><stop offset="55%" stopColor="#c98f5e" /><stop offset="100%" stopColor="#9c6a40" /></linearGradient>
        <linearGradient id="guanteM" x1="0" y1="0" x2="1" y2="0"><stop offset="0%" stopColor="#4a5160" /><stop offset="55%" stopColor="#2a2f3a" /><stop offset="100%" stopColor="#14171d" /></linearGradient>
      </defs>
      <rect x={-64} y={80} width={128} height={420} rx={50} fill={F} stroke={L} strokeWidth={4} />
      <rect x={-80} y={-70} width={160} height={190} rx={56} fill={F} stroke={L} strokeWidth={4} />
      {[[-58, 70], [-20, 55], [20, 60], [58, 75]].map(([fx, fl], i) => (
        <rect key={i} x={fx - 17} y={-70 - (i === 1 && dedo ? 150 : fl)} width={34} height={(i === 1 && dedo ? 150 : fl) + 40} rx={17} fill={F} stroke={L} strokeWidth={3} />
      ))}
      <rect x={-128} y={-20} width={34} height={110} rx={17} fill={F} stroke={L} strokeWidth={3} transform="rotate(-38 -110 60)" />
      <path d="M -80 -20 Q -30 -50 20 -20" stroke="rgba(255,255,255,0.28)" strokeWidth={6} fill="none" strokeLinecap="round" />
    </g>
  );
};
const Polvo: React.FC<{n?: number; color?: string; vel?: number}> = ({n = 30, color = 'rgba(255,240,210,0.5)', vel = 1}) => {
  const {s} = useS();
  return (
    <svg width={1080} height={1920} style={{position: 'absolute', inset: 0}}>
      {Array.from({length: n}).map((_, i) => {
        const x = h(i * 3 + 1) * 1080 + Math.sin(s * 0.6 + i) * 34;
        const y = (((h(i * 7 + 2) * 1920 - s * (14 + h(i) * 26) * vel) % 1920) + 1920) % 1920;
        return <circle key={i} cx={x} cy={y} r={2 + h(i * 5) * 4} fill={color} opacity={0.25 + h(i * 11) * 0.4} />;
      })}
    </svg>
  );
};

// torniquete de metal cepillado (visto de frente, 3 brazos que giran)
const Torno: React.FC<{x: number; y: number; k?: number; giro: number; luz: number; brillo?: string}> = ({x, y, k = 1.1, giro, luz, brillo = '#35ff6a'}) => (
  <g transform={`translate(${x} ${y}) scale(${k})`}>
    <defs>
      <linearGradient id="metalT" x1="0" y1="0" x2="1" y2="0"><stop offset="0%" stopColor="#4d535b" /><stop offset="22%" stopColor="#c9ced4" /><stop offset="50%" stopColor="#8e949c" /><stop offset="78%" stopColor="#d9dde2" /><stop offset="100%" stopColor="#474c54" /></linearGradient>
      <linearGradient id="brazoT" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#e6e9ed" /><stop offset="50%" stopColor="#9aa0a8" /><stop offset="100%" stopColor="#5a6068" /></linearGradient>
    </defs>
    <ellipse cx={0} cy={560} rx={290} ry={44} fill="rgba(0,0,0,0.45)" />
    <rect x={-170} y={-430} width={340} height={990} rx={44} fill="url(#metalT)" stroke="#2d3137" strokeWidth={6} />
    {Array.from({length: 26}).map((_, i) => <line key={i} x1={-160} x2={160} y1={-400 + i * 36} y2={-400 + i * 36 + (h(i) - 0.5) * 6} stroke="rgba(255,255,255,0.10)" strokeWidth={2} />)}
    <rect x={-190} y={158} width={380} height={46} rx={23} fill="#07090d" stroke="#aab0b8" strokeWidth={6} />
    <rect x={-150} y={170} width={300} height={8} rx={4} fill="rgba(255,255,255,0.14)" />
    <rect x={-120} y={-80} width={240} height={120} rx={22} fill="#10151c" stroke="#2d3137" strokeWidth={4} />
    <circle cx={0} cy={-20} r={34} fill={luz > 0.5 ? brillo : '#243324'} stroke="#0a0f0a" strokeWidth={5} />
    {luz > 0.5 && <circle cx={0} cy={-20} r={34 + 26 * luz} fill={brillo} opacity={0.22 * luz} />}
    <text x={0} y={30} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={30} fill={luz > 0.5 ? brillo : '#3a4a3a'}>$</text>
    <g transform={`translate(0 -430) rotate(${giro})`}>
      {[0, 120, 240].map((a) => (
        <g key={a} transform={`rotate(${a})`}>
          <rect x={-22} y={-340} width={44} height={340} rx={22} fill="url(#brazoT)" stroke="#2d3137" strokeWidth={4} />
          <circle cx={0} cy={-340} r={30} fill="url(#brazoT)" stroke="#2d3137" strokeWidth={4} />
        </g>
      ))}
      <circle r={66} fill="url(#brazoT)" stroke="#2d3137" strokeWidth={6} />
      <circle r={26} fill="#2d3137" />
    </g>
  </g>
);

const Pase: React.FC<{x: number; y: number; r?: number; k?: number; txt?: string; color?: string}> = ({x, y, r = 0, k = 1, txt = '$10', color = GOLD}) => (
  <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
    <rect x={-168} y={-98} width={344} height={206} rx={18} fill="rgba(0,0,0,0.35)" />
    <path d="M -170 -100 H 170 V -30 A 22 22 0 0 0 170 14 V 100 H -170 V 14 A 22 22 0 0 0 -170 -30 Z" fill="#f6ecd2" stroke="#b79a52" strokeWidth={5} />
    <line x1={-120} y1={-100} x2={-120} y2={100} stroke="#b79a52" strokeWidth={3} strokeDasharray="10 8" />
    <text x={30} y={-34} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={34} fill="#6b5524">PASE</text>
    <text x={30} y={52} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={84} fill={color === GOLD ? '#a8780f' : color}>{txt}</text>
    <path d="M -170 -100 L -40 -100 L -130 100 L -170 100 Z" fill="rgba(255,255,255,0.25)" />
  </g>
);


// ---------- tiempos (todo atado a palabras del guion) ----------
const CUENTA = en('cuenta'), VAYAS = en('vayas'), OFENSA = en('ofensa'), MODELO = en('modelo');
const ESTUD = en('estudiaron'), MILES = en('miles'), SET = en('setenta'), MES1 = en('mes');
const CUANT = en('cuantas'), CUATRO = en('cuatro'), ESO = en('eso'), SALE = en('sale'), DIEC = en('diecisiete');
const CRUZ = en('cruzaban'), PUERTA2 = en('puerta', 2), DIEZ = en('diez');
const CON = en('con', 2), PERD = en('perdia'), SEIS = en('seiscientos'), DURANTE = en('durante'), MEMB = en('membresia');
const PORQUE = en('porque'), FIRMAR = en('firmar'), PAGAS = en('pagas'), SER = en('ser'), NUNCA = en('nunca');
const HAZ = en('haz'), DIVIDE = en('divide'), ENTRE = en('entre'), VECES2 = en('veces', 2), MES3 = en('mes', 3), PASA = en('pasa'), PASE3 = en('pase', 3), GANANDO = en('ganando');
const DALE = en('dale'), FUI = en('fui');

const FIN_A = ESTUD + 0.3;
const SLOT = {x: 540, y: 1150 + 187};

// ================= SITIO A: torniquete que se traga el billete (E1) =================
const A_CAM = [P(0, 540, 1000, 1.0), P(ESTUD, 540, 1153, 1.2)];
const SLOT_SCR = {x: 540, y: 1000 + (SLOT.y - P(0, 540, 1153, 1.2).y) * 1.2};
const SitioA: React.FC = () => {
  const {s, spr} = useS();
  const luz = spr(MODELO, 10, 120);
  const giro = Math.max(0, s - CUENTA) * 120 + 26 * Math.max(0, golpe(s, OFENSA, 12, 3));
  const pts: [number, number][] = [[930, 380], [260, 600], [840, 900], [560, 1180], [SLOT.x, SLOT.y], [SLOT.x, SLOT.y + 220]];
  const q = enCamino(s, pts, -0.35, VAYAS + 0.5);
  const sacude = sacudida(s, [VAYAS + 0.4], 8);
  return (
    <AbsoluteFill>
      <Camara paradas={A_CAM}>
        <Textura tipo="fibra" base="radial-gradient(circle at 50% 58%, #3d3526 0%, #1c1812 62%, #0a0907 100%)" linea="rgba(255,200,61,0.22)" luz="rgba(255,200,61,0.14)" semilla={2} />
        <Brillo x={540} y={1180} r={620} color="rgba(255,200,61,0.30)" />
        <svg width={1080} height={1920} style={{position: 'absolute', inset: 0, transform: `translate(${sacude.x}px, ${sacude.y}px)`}}>
          <defs><clipPath id="clipA"><rect x={0} y={0} width={1080} height={SLOT.y + 4} /></clipPath></defs>
          <Torno x={540} y={1150} k={1.1} giro={giro} luz={luz} />
          <g clipPath="url(#clipA)">
            <Bill x={q.x} y={q.y} r={q.p * 520 - 40} k={1.15 - 0.55 * q.p} txt="70" halo="rgba(255,200,61,0.9)" />
          </g>
        </svg>
        <Ondas x={SLOT.x} y={SLOT.y} t0={MODELO} color="#35ff6a" radio={520} />
        <Ondas x={SLOT.x} y={SLOT.y} t0={VAYAS + 0.45} color={GOLD} radio={300} />
      </Camara>
    </AbsoluteFill>
  );
};

// ================= SITIO B: fichas de socios y calendario (E2 y E3) =================
const CAL = {x0: 100, y0: 560, w: 880};
const cell = (c: number, r: number) => ({x: CAL.x0 + (CAL.w / 7) * (c + 0.5), y: 700 + 164 * (r + 0.5)});
const XS = [cell(1, 0), cell(4, 1), cell(2, 2), cell(5, 2)];
const XT = [CUATRO, CUATRO + 0.4, CUATRO + 0.8, CUATRO + 1.2];
const B_CAM = [P(ESTUD, 440, 1000, 1.12), P(CUANT - 0.3, 640, 1000, 1.12), P(ESO - 0.15, XS[3].x, XS[3].y, 1.25)];
const B_END = P(0, XS[3].x, XS[3].y, 1.25);
const PX = 540 + (XS[3].x - B_END.x) * B_END.zoom;
const PY = 1000 + (XS[3].y - B_END.y) * B_END.zoom;

const SitioB: React.FC = () => {
  const {s, spr} = useS();
  const calY = (1 - eo(ro(s, CUANT - 0.1, CUANT + 0.7))) * 1900;
  const fuera = eio(ro(s, CUANT - 0.2, CUANT + 0.6)) * 1700;
  // mano con marcador
  const wpT = [CUATRO - 0.5, XT[0] - 0.08, XT[1] - 0.08, XT[2] - 0.08, XT[3] - 0.08, XT[3] + 0.6];
  const wpX = [1250, XS[0].x, XS[1].x, XS[2].x, XS[3].x, 1250];
  const wpY = [330, XS[0].y, XS[1].y, XS[2].y, XS[3].y, 330];
  const ez = {...clamp, easing: Easing.inOut(Easing.cubic)};
  const tx = interpolate(s, wpT, wpX, ez), ty0 = interpolate(s, wpT, wpY, ez);
  const press = XT.reduce((a, t) => a + Math.max(0, golpe(s, t, 22, 9)), 0);
  const ty = ty0 + calY * 0 - press * 14 + calY;
  const kM = 0.62;
  const manoVis = s > wpT[0] - 0.1 && s < wpT[5] + 0.3;
  const bq = enCamino(s, [[80, 660], [520, 880], [300, 1080], [760, 1120], [1010, 900], [930, 640]], ESTUD + 0.2, CUANT + 0.7);
  return (
    <AbsoluteFill>
      <Camara paradas={B_CAM}>
        <Textura tipo="fibra" base="linear-gradient(180deg, #1c2128, #2c333d 50%, #14181e)" linea="rgba(200,210,225,0.18)" luz="rgba(255,200,61,0.12)" semilla={4} />
        <Brillo x={540} y={1000} r={640} color="rgba(255,200,61,0.20)" />
        <svg width={1080} height={1920} style={{position: 'absolute', inset: 0}}>
          {Array.from({length: 14}).map((_, i) => {
            const row = Math.floor(i / 5);
            const fx = 160 + (i % 5) * 190 + (row % 2) * 46 + (h(i) - 0.5) * 18;
            const fy = 760 + row * 250;
            const k = spr(MILES + i * 0.11, 12, 90);
            const st = spr(SET + 0.1 * i, 9, 190);
            const y = fy - (1 - k) * 1400 + fuera;
            const r = (h(i * 3) - 0.5) * 16 + (1 - k) * 25;
            return (
              <g key={i} transform={`translate(${fx} ${y}) rotate(${r})`} opacity={k > 0.001 ? 1 : 0}>
                <rect x={-72} y={-100} width={152} height={210} rx={16} fill="rgba(0,0,0,0.35)" />
                <rect x={-76} y={-105} width={152} height={210} rx={16} fill="#e9edf3" stroke="#8d97a8" strokeWidth={4} />
                <rect x={-76} y={-105} width={152} height={44} rx={16} fill={['#3b6fd6', '#2fa37a', '#c25b3a', '#8a54c9'][i % 4]} />
                <circle cx={0} cy={-22} r={34} fill={['#c98f5e', '#e0b48a', '#8a5a36', '#f0c9a4'][(i * 3) % 4]} />
                <rect x={-30} y={22} width={60} height={14} rx={7} fill="#aab2bf" />
                <rect x={-44} y={46} width={88} height={10} rx={5} fill="#c6ccd6" />
                <g transform={`translate(8 70) rotate(${-14 + h(i + 9) * 8}) scale(${st})`}>
                  <rect x={-50} y={-20} width={100} height={40} rx={20} fill={GOLD} stroke="#8a6a10" strokeWidth={3} />
                  <text y={11} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={30} fill="#3a2a00">$70</text>
                </g>
              </g>
            );
          })}
          <Cartera x={250} y={1400} k={0.55} grosor={1 - 0.7 * eio(ro(s, SET + 0.4, MES1 + 0.5))} />
          {/* calendario de papel */}
          <g transform={`translate(0 ${calY})`}>
            <rect x={CAL.x0 + 8} y={CAL.y0 + 14} width={CAL.w} height={1000} rx={20} fill="rgba(0,0,0,0.4)" />
            <rect x={CAL.x0} y={CAL.y0} width={CAL.w} height={1000} rx={20} fill="#f4efe3" stroke="#b9ad8f" strokeWidth={5} />
            <rect x={CAL.x0} y={CAL.y0} width={CAL.w} height={120} rx={20} fill="#c4352f" />
            <rect x={CAL.x0} y={CAL.y0 + 90} width={CAL.w} height={30} fill="#c4352f" />
            {[0, 1, 2, 3, 4, 5].map((i) => <circle key={i} cx={CAL.x0 + 100 + i * 136} cy={CAL.y0 + 8} r={14} fill="#2b2b2b" />)}
            <text x={540} y={CAL.y0 + 84} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={56} fill="#fff">ESTE MES</text>
            {Array.from({length: 35}).map((_, i) => {
              const c = i % 7, r = Math.floor(i / 7), p = cell(c, r);
              return (
                <g key={i}>
                  <rect x={p.x - 56} y={p.y - 72} width={112} height={144} fill="none" stroke="#d3c9b0" strokeWidth={2} />
                  {i < 31 && <text x={p.x - 46} y={p.y - 42} fontFamily={FONT} fontWeight={600} fontSize={26} fill="#8c8571">{i + 1}</text>}
                  {[0, 1, 2].map((j) => <circle key={j} cx={p.x - 40 + h(i * 7 + j) * 80} cy={p.y - 20 + h(i * 5 + j * 3) * 80} r={2 + h(i + j) * 3} fill="#bdb59c" opacity={0.5} />)}
                </g>
              );
            })}
            {XS.map((p, i) => {
              const a = ro(s, XT[i] - 0.05, XT[i] + 0.22);
              if (a <= 0) return null;
              const L = 46;
              return (
                <g key={i} transform={`translate(${p.x} ${p.y}) scale(${1 + 0.18 * Math.max(0, golpe(s, XT[i], 20, 8))})`}>
                  <line x1={-L} y1={-L} x2={-L + 2 * L * Math.min(1, a * 2)} y2={-L + 2 * L * Math.min(1, a * 2)} stroke={RED} strokeWidth={16} strokeLinecap="round" />
                  {a > 0.5 && <line x1={L} y1={-L} x2={L - 2 * L * Math.min(1, (a - 0.5) * 2)} y2={-L + 2 * L * Math.min(1, (a - 0.5) * 2)} stroke={RED} strokeWidth={16} strokeLinecap="round" />}
                </g>
              );
            })}
          </g>
          <Bill x={bq.x} y={bq.y} r={-30 + Math.sin(s * 3) * 8} k={0.48} txt="70" halo="rgba(255,200,61,0.8)" />
          {manoVis && (
            <g transform={`translate(${tx + 52} ${ty - 179}) rotate(200) scale(${kM})`}>
              <Mano x={0} y={0} />
              <rect x={-34} y={-310} width={28} height={130} rx={14} fill="#d92b2b" stroke="#6b0f0f" strokeWidth={3} />
              <rect x={-34} y={-322} width={28} height={30} rx={10} fill="#2b2b2b" />
            </g>
          )}
        </svg>
        <Chip texto="$70 al mes" x={540} y={520} t0={SET} t1={CUANT - 0.3} size={72} color={GOLD} />
      </Camara>
      <Polvo n={24} />
    </AbsoluteFill>
  );
};

// ================= SITIO D: la puerta de cristal, el pase y la pila (E4 y E5) =================
const D_CAM = [P(ESO - 0.3, 380, 1050, 1.25), P(DIEZ + 0.5, 700, 1050, 1.25), P(CON, 700, 1050, 1.25), P(SEIS - 0.3, 540, 1000, 1.0)];
const SitioD: React.FC = () => {
  const {s, spr} = useS();
  const cc = tono(s, [ESO - 0.3, SALE + 0.2], [GOLD, RED], 0.8);
