// ================= SITIO F: calculadora, torniquete y regreso (E7 y E8) =================
const KEYS = [['C', '±', '%', '÷'], ['7', '8', '9', '×'], ['4', '5', '6', '−'], ['1', '2', '3', '+'], ['0', '.', '', '=']];
const kpos = (c: number, r: number) => ({x: -150 + c * 100, y: -170 + r * 118});
const PRESS: {t: number; c: number; r: number}[] = [{t: DIVIDE + 0.05, c: 0, r: 1}, {t: DIVIDE + 0.5, c: 0, r: 4}, {t: ENTRE, c: 3, r: 0}, {t: VECES2, c: 0, r: 2}, {t: MES3, c: 3, r: 4}];
const F_CAM = [P(HAZ, 540, 1000, 1.0), P(DIVIDE - 0.2, 420, 1000, 1.15), P(PASE3 + 0.4, 420, 1000, 1.15), P(GANANDO + 0.5, 540, 1100, 1.0), P(DALE, 540, 1100, 1.0), P(DALE + 12, 520, 1060, 1.07)];
const SitioF: React.FC = () => {
  const {s, spr} = useS();
  const sub = spr(HAZ - 0.25, 13, 90);
  const out = eio(ro(s, GANANDO - 0.15, GANANDO + 0.6));
  const px = 400 - out * 900, py = 1000 + (1 - sub) * 1500 + out * 260;
  const pr = (c: number, r: number) => PRESS.reduce((a, q) => a + (q.c === c && q.r === r ? Math.max(0, golpe(s, q.t, 18, 7)) * 0.5 + (s > q.t && s < q.t + 0.25 ? 0.5 : 0) : 0), 0);
  const expr = s < PRESS[0].t ? '' : s < PRESS[1].t ? '7' : s < PRESS[2].t ? '70' : s < PRESS[3].t ? '70 ÷' : s < PRESS[4].t ? '70 ÷ 4' : '70 ÷ 4';
  const res = s >= PRESS[4].t;
  const wpT = [PRESS[0].t - 0.3, ...PRESS.map((q) => q.t - 0.05), PRESS[4].t + 0.7];
  const wpX = [kpos(0, 1).x + 200, ...PRESS.map((q) => kpos(q.c, q.r).x), kpos(3, 4).x + 220];
  const wpY = [kpos(0, 1).y + 700, ...PRESS.map((q) => kpos(q.c, q.r).y), kpos(3, 4).y + 800];
  const ez = {...clamp, easing: Easing.inOut(Easing.cubic)};
  const fx = interpolate(s, wpT, wpX, ez), fy = interpolate(s, wpT, wpY, ez);
  const fPress = PRESS.reduce((a, q) => a + Math.max(0, golpe(s, q.t, 22, 9)), 0);
  const giro = Math.max(0, s - HAZ) * 120 + 40;
  const luz = 1;
  // monedas hacia el dueno
  const bag = {x: 900, y: 640};
  const bagK = 1 + 0.1 * Math.max(0, golpe(s, GANANDO + 0.9, 14, 6)) + 0.04 * Math.sin(s * 3);
  // billete que regresa a la cartera (E8)
  const bq = enCamino(s, [[SLOT.x, SLOT.y + 10], [470, 1190], [330, 1250], [240, 1420], [236, 1530]], DALE - 0.1, FUI - 0.25);
  const wal = spr(DALE - 0.6, 12, 110);
  const dentroW = ro(s, FUI - 0.35, FUI - 0.1);
  return (
    <AbsoluteFill>
      <Camara paradas={F_CAM}>
        <Textura tipo="fibra" base="radial-gradient(circle at 50% 58%, #3d3526 0%, #1c1812 62%, #0a0907 100%)" linea="rgba(255,200,61,0.22)" luz="rgba(255,200,61,0.14)" semilla={2} />
        <Brillo x={540} y={1150} r={620} color="rgba(255,200,61,0.30)" />
        <svg width={1080} height={1920} style={{position: 'absolute', inset: 0}}>
          <defs>
            <clipPath id="clipF"><rect x={0} y={0} width={1080} height={SLOT.y + 4} /></clipPath>
            <radialGradient id="monedaF" cx="35%" cy="30%" r="75%"><stop offset="0%" stopColor="#fff2a8" /><stop offset="60%" stopColor="#ffc83d" /><stop offset="100%" stopColor="#a8780f" /></radialGradient>
            <radialGradient id="bolsaF" cx="40%" cy="30%" r="80%"><stop offset="0%" stopColor="#d9b97a" /><stop offset="60%" stopColor="#a47c3a" /><stop offset="100%" stopColor="#5a3f14" /></radialGradient>
          </defs>
          <Torno x={540} y={1150} k={1.1} giro={giro} luz={luz} />
          {/* bolsa del dueno */}
          <g transform={`translate(${bag.x} ${bag.y}) scale(${bagK * (0.2 + 0.8 * ro(s, GANANDO - 0.3, GANANDO + 0.3))})`}>
            <ellipse cx={0} cy={150} rx={120} ry={20} fill="rgba(0,0,0,0.4)" />
            <path d="M -70 -70 Q -150 20 -120 110 Q 0 160 120 110 Q 150 20 70 -70 Q 0 -40 -70 -70 Z" fill="url(#bolsaF)" stroke="#3d2a0b" strokeWidth={5} />
            <path d="M -70 -70 Q -90 -120 -40 -120 L 40 -120 Q 90 -120 70 -70" fill="#c9a25a" stroke="#3d2a0b" strokeWidth={5} />
            <text x={0} y={70} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={110} fill="#3d2a0b">$</text>
          </g>
          {s > GANANDO && Array.from({length: 14}).map((_, i) => {
            const t0 = GANANDO + 0.2 + i * 0.3;
            const u = (s - t0) / 1.0;
            if (u < 0 || u > 1) return null;
            const x = SLOT.x + (bag.x - SLOT.x) * u, y = SLOT.y + (bag.y - SLOT.y) * u - Math.sin(u * Math.PI) * 330;
            return (
              <g key={i} transform={`translate(${x} ${y}) rotate(${u * 540})`}>
                <circle r={28} fill="url(#monedaF)" stroke="#7a560a" strokeWidth={4} />
                <text y={11} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={32} fill="#7a560a">$</text>
              </g>
            );
          })}
          {/* billete de regreso */}
          {s > DALE - 0.15 && (
            <g clipPath={ro(s, DALE - 0.1, DALE + 0.4) < 1 ? 'url(#clipF)' : undefined} opacity={1 - dentroW}>
              <Bill x={bq.x} y={bq.y} r={-30 + bq.p * 380} k={0.9 - 0.55 * bq.p} txt="70" halo="rgba(255,200,61,0.9)" />
            </g>
          )}
          <g opacity={wal > 0.01 ? 1 : 0}>
            <Cartera x={236} y={1600} k={0.8 * wal * (1 + 0.06 * Math.max(0, golpe(s, FUI, 14, 6)))} oro grosor={1} />
          </g>
          {/* celular */}
          <g transform={`translate(${px} ${py})`}>
            <rect x={-264} y={-512} width={528} height={1044} rx={78} fill="rgba(0,0,0,0.45)" transform="translate(10 16)" />
            <rect x={-260} y={-520} width={520} height={1040} rx={76} fill="#12151c" stroke="#4a5262" strokeWidth={8} />
            <rect x={-232} y={-492} width={464} height={984} rx={54} fill="#0c1a28" />
            <rect x={-200} y={-452} width={400} height={230} rx={22} fill="#06101a" stroke="#1d3347" strokeWidth={3} />
            <text x={176} y={-340} textAnchor="end" fontFamily={FONT} fontWeight={600} fontSize={64} fill="#cfe2f3">{expr}</text>
            {res && <text x={176} y={-252} textAnchor="end" fontFamily={FONT} fontWeight={800} fontSize={84} fill={RED}>= $17.5</text>}
            {KEYS.map((row, r) => row.map((k, c) => {
              if (!k) return null;
              const kp = kpos(c, r), pv = pr(c, r);
              const op = c === 3;
              return (
                <g key={k + c + r} transform={`translate(${kp.x} ${kp.y}) scale(${1 - 0.1 * Math.min(1, pv)})`}>
                  <rect x={-42} y={-42} width={84} height={84} rx={24} fill={pv > 0.2 ? (op ? '#ffe28a' : '#6f8fb0') : op ? GOLD : '#22364a'} />
                  <text y={14} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={40} fill={op ? '#3a2a00' : '#e4eef8'}>{k}</text>
                </g>
              );
            }))}
            <g transform={`translate(${fx} ${fy + fPress * 10}) rotate(14)`}>
              <rect x={-30} y={0} width={60} height={250} rx={30} fill="url(#piel9)" stroke="#7a4f2c" strokeWidth={4} />
              <rect x={-16} y={12} width={32} height={18} rx={9} fill="rgba(255,255,255,0.22)" />
            </g>
          </g>
          <g opacity={ro(s, PASE3 - 0.1, PASE3 + 0.2)} transform={`translate(0 ${Math.sin(s * 2.4) * 8})`}>
            <Pase x={850} y={760} r={-8} k={0.78 * spr(PASE3 - 0.05, 9, 150)} txt="$10" />
          </g>
        </svg>
        <Chip texto="FUI" x={540} y={600} t0={FUI} t1={9999} size={96} color={GOLD} />
      </Camara>
      <Polvo n={22} />
    </AbsoluteFill>
  );
};

